def f(g):
    H,W=len(g),len(g[0]); out=[row[:] for row in g]
    fives=[(r,c) for r in range(H) for c in range(W) if g[r][c]==5]
    # group into components via 8-conn
    seen=set(); groups=[]
    for p in fives+[ (r,c) for r in range(H) for c in range(W) if g[r][c]!=5]:
        pass
    # simple: cluster nonzeros by adjacency ignoring 0; marker is a 5 not adjacent to other nonzeros? try: marker 5 has zero nonzero-neighbors
    # Instead: shape = largest connected component of nonzeros; shape_marker = a 5 inside/near it; free marker = isolated 5.
    cells={(r,c):v for r in range(H) for c in range(W) for v in [g[r][c]] if v}
    from collections import deque
    comps=[]
    used=set()
    for p in cells:
        if p in used: continue
        q=deque([p]); comp=[]; used.add(p)
        while q:
            (r,c)=q.popleft(); comp.append(((r,c),cells[(r,c)]))
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    n=((r+dr),(c+dc))
                    if n in cells and n not in used:
                        used.add(n); q.append(n)
        comps.append(comp)
    comps.sort(key=lambda comp:-len(comp))
    main=max(comps,key=lambda comp:len(comp))
    # main should contain exactly one 5
    ms=[p for p,v in main if v==5]
    assert len(ms)==1, ms
    sm=ms[0]; mr=(sm[0]-min(p[0] for p,_ in main), sm[1]-min(p[1] for p,_ in main))
    free=[p for p in comps[-1] if True for _ in [] ]
    # free marker: a 5 whose component != main
    for comp in comps:
        if comp is main: continue
        if [(p,v) for p,v in comp if v==5]:
            fm=min((p for p,v in comp), key=lambda p: abs(p[0]-sm[0])+abs(p[1]-sm[1]))
            break
    nt=(fm[0]-mr[0], fm[1]-mr[1])
    base_r=min(p[0] for p,_ in main); base_c=min(p[1] for p,_ in main)
    for (pr,pc),v in main:
        out[pr+nt[0]-base_r][pc+nt[1]-base_c]=v
    return out

